def calculator_tool(expression: str) -> str:
    try:
        return str(eval(expression, {"__builtins__": {}}))
    except Exception as e:
        return f'Error: {e}'

# Simulated ReAct trace
trace = [
    ('Thought', 'User wants 482 * 19. I need to call calculator_tool.'),
    ('Action',  'calculator_tool("482 * 19")'),
    ('Observation', calculator_tool('482 * 19')),
    ('Final Answer', 'The product of 482 and 19 is 9,158.')
]

for step, content in trace:
    print(f'[{step:12s}]: {content}')
